/*
 * Servo Sweep — Sweep a servo motor from 0° to 180° and back
 */

#include <Servo.h>

Servo myServo;
int pos = 0;
int dir = 1;

void setup() {
  myServo.attach(9);
  Serial.begin(9600);
}

void loop() {
  pos += dir;
  if (pos >= 180 || pos <= 0) dir = -dir;
  myServo.write(pos);
  Serial.println(pos);
  delay(15);
}
